import{_ as o,C as i,c as r,o as s,ax as t,G as n}from"./chunks/framework.DHqKNX4U.js";const _=JSON.parse('{"title":"Index Admin API","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"api/index-admin.md","filePath":"api/index-admin.md"}'),d={name:"api/index-admin.md"};function c(h,e,l,p,m,u){const a=i("OAOperation");return s(),r("div",null,[e[0]||(e[0]=t('<h1 id="index-admin-api" tabindex="-1">Index Admin API <a class="header-anchor" href="#index-admin-api" aria-label="Permalink to &quot;Index Admin API&quot;">​</a></h1><p>Observability and maintenance for the search engine (Meilisearch). These endpoints power the <strong>Admin → Index</strong> page and are intended for troubleshooting indexing. All routes require <code>manage:all</code> (Super Administrator) permission, and the API key of the search engine is never returned.</p><h2 id="get-overview" tabindex="-1">Get Overview <a class="header-anchor" href="#get-overview" aria-label="Permalink to &quot;Get Overview&quot;">​</a></h2><p>Returns instance-level information (host, version, health, database size), metadata for the <code>emails</code> index (document count, primary key, indexing state, field distribution), and per-ingestion-source document counts taken directly from the search index&#39;s facet distribution — not the database.</p>',4)),n(a,{operationId:"getSearchIndexOverview"}),e[1]||(e[1]=t('<h2 id="get-tasks" tabindex="-1">Get Tasks <a class="header-anchor" href="#get-tasks" aria-label="Permalink to &quot;Get Tasks&quot;">​</a></h2><p>Returns a cursor-paginated list of Meilisearch tasks for the <code>emails</code> index (e.g. <code>documentAdditionOrUpdate</code>), including status, received/indexed document counts, duration, timestamps, and any error. Filter with <code>statuses</code> and <code>types</code>, and page with <code>limit</code> + <code>from</code> (use the <code>next</code> cursor from the previous response).</p>',2)),n(a,{operationId:"getSearchIndexTasks"}),e[2]||(e[2]=t('<h2 id="clean-up-orphaned-documents" tabindex="-1">Clean Up Orphaned Documents <a class="header-anchor" href="#clean-up-orphaned-documents" aria-label="Permalink to &quot;Clean Up Orphaned Documents&quot;">​</a></h2><p>Queues a background sweep that removes documents from the <code>emails</code> index whose archived email no longer exists in the database.</p><p>These entries are left behind when a deletion removes the database row but its search index counterpart never completes — for example if the search engine was unavailable at the time. They appear to users as search results that cannot be opened. The sweep clears whole blocks first, for ingestion sources that were deleted, then compares the remaining document ids against the database one page at a time.</p><p>No emails, attachments or stored files are touched: the database and the stored <code>.eml</code> files are the archive&#39;s source of truth, and the index is rebuilt from them by a reindex. The response reports the surplus of index documents over archived emails as <code>estimatedOrphans</code>, which is a floor rather than an exact figure — emails archived but not yet indexed offset orphans one for one. The exact number removed is written to the worker log and the job&#39;s result on <strong>Admin → Jobs</strong>.</p><p>Only one sweep runs at a time. A request made while one is already queued or running joins it instead of starting a second, and says so via <code>alreadyRunning</code> in the response. Once a sweep has finished, the action can be triggered again — including after a failed run.</p>',5)),n(a,{operationId:"cleanupOrphanedIndexDocuments"})])}const g=o(d,[["render",c]]);export{_ as __pageData,g as default};
